 "content": "def transform(grid):
    """Encode each 3x3 patch by its non-background object color."""
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w // 3)] for _ in range(h // 3)]
    for tr in range(h // 3):
        for tc in range(w // 3):
            colors = {
                grid[r][c]
                for r in range(tr * 3, tr * 3 + 3)
                for c in range(tc * 3, tc * 3 + 3)
                if grid[r][c] not in (0, 5)
            }
            if colors:
                out[tr][tc] = min(colors)
    return out
